					g.Progress.incrementRequests()
					return
				case successChan <- successfulGuess{guess: guess, result: res}:
				}
			}

			g.Progress.incrementRequests()

			select {
			case <-ctx.Done():
			case <-time.After(g.Opts.Delay):
			}
		}
	}
